import{_ as t,o,c as r,ak as a}from"./chunks/framework.sV-XtlWr.js";const f=JSON.parse('{"title":"Source control","description":"Connect the dashboard to your GitHub, GitLab or Bitbucket repository with an SCM token, and see which features read or write through it.","frontmatter":{"title":"Source control","description":"Connect the dashboard to your GitHub, GitLab or Bitbucket repository with an SCM token, and see which features read or write through it.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/source-control.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/source-control.html"}],["meta",{"property":"og:title","content":"Source control | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Connect the dashboard to your GitHub, GitLab or Bitbucket repository with an SCM token, and see which features read or write through it."}]]},"headers":[],"relativePath":"guide/source-control.md","filePath":"guide/source-control.md","lastUpdated":1791285777000}'),s={name:"guide/source-control.md"};function i(n,e,d,h,c,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="source-control" tabindex="-1">Source control <a class="header-anchor" href="#source-control" aria-label="Permalink to &quot;Source control&quot;">​</a></h1><p>Piwi reads your repository through the Git host&#39;s API with an <strong>SCM token</strong> (a personal or project access token for GitHub, GitLab or Bitbucket). Nothing needs it to store runs, but every feature that looks at the code behind a failure, or writes back to a pull request, goes through it.</p><h2 id="what-uses-it" tabindex="-1">What uses it <a class="header-anchor" href="#what-uses-it" aria-label="Permalink to &quot;What uses it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>What it does with the repository</th><th>Access</th></tr></thead><tbody><tr><td><a href="/features/ai-diagnosis.html#scm-grounded-context">AI diagnosis</a></td><td>Reads the commits and diffs since the last green run, and the full source of the most suspect files</td><td>read</td></tr><tr><td>The failure cluster&#39;s <strong>What changed</strong> panel</td><td>Lists commits, shows their diffs, and lets you pin a baseline commit</td><td>read</td></tr><tr><td><a href="/features/uncovered-changes.html">Uncovered changes</a></td><td>Diffs the run&#39;s commit against the pull request&#39;s base, or the last passing run, and flags changed files no test reached</td><td>read</td></tr><tr><td><a href="/features/failure-clusters.html#did-the-fix-work">Did the fix work?</a></td><td>Checks whether the commits after a fix touched the failing files</td><td>read</td></tr><tr><td><a href="/features/notifications.html">Notifications</a></td><td>Names the author of the fixing commit on <code>cluster.fixed</code> and <code>cluster.regressed</code></td><td>read</td></tr><tr><td>Ownership and the default branch</td><td>Reads <code>CODEOWNERS</code> for test owners, and the repository&#39;s default branch when the project sets none</td><td>read</td></tr><tr><td><a href="/features/pr-feedback.html">Pull-request feedback</a></td><td>Posts a summary comment and a commit status</td><td>write</td></tr><tr><td><a href="/features/pr-feedback.html#re-run-from-the-dashboard">Re-run in CI</a></td><td>Dispatches a workflow or pipeline</td><td>write</td></tr><tr><td><a href="/features/auto-heal.html">Auto-heal PRs</a></td><td>Opens a pull request with a locator fix</td><td>write</td></tr></tbody></table><p>Every call is best-effort: a missing token, a private repository the token cannot see or an unreachable host is logged, and the feature shows nothing rather than failing a run.</p><h2 id="set-the-token" tabindex="-1">Set the token <a class="header-anchor" href="#set-the-token" aria-label="Permalink to &quot;Set the token&quot;">​</a></h2><ul><li><strong>Instance-wide</strong>: <strong>Settings → AI → Repository access</strong>. Every project uses it unless it has its own.</li><li><strong>Per project</strong>: the <strong>Source control</strong> section of the project&#39;s <strong>Settings</strong> tab, field <strong>SCM token</strong>. It overrides the instance-wide token for that project. Prefer one per project for write access: an instance-wide write token can write everywhere it reaches.</li></ul><p>A token is stored encrypted with <a href="/reference/configuration.html#general"><code>PIWI_SECRET_KEY</code></a> and never returned by the API; the field shows that one is stored. Leave the field empty to keep it. To remove it, save the instance-wide field empty, or click <strong>Remove stored token</strong> under the project field.</p><p>Public repositories work without a token for the read features, within the host&#39;s rate limit for anonymous calls. A private repository needs one, except on the desktop app with a linked folder (below).</p><h3 id="on-the-desktop-app" tabindex="-1">On the desktop app <a class="header-anchor" href="#on-the-desktop-app" aria-label="Permalink to &quot;On the desktop app&quot;">​</a></h3><p>The <a href="/features/desktop.html">desktop app</a> needs no token for the read features. When a project is <a href="/features/desktop.html#projects-from-local-folders">linked to a folder</a> that is a clone of the repository (one of its remotes points at the run&#39;s remote URL), Piwi reads the commits, diffs and files with <code>git</code> in that folder, on your machine. A commit or branch the clone does not have is asked of the host as above, so run <code>git fetch</code> in the folder to see commits pushed since your last fetch. With a token set, the host is read instead, as on a server, and the write features always need one.</p><h3 id="which-repository" tabindex="-1">Which repository <a class="header-anchor" href="#which-repository" aria-label="Permalink to &quot;Which repository&quot;">​</a></h3><p>Piwi takes the repository from the run: the reporter records the Git remote URL, the branch and the commit of the checkout it runs in (see <a href="/reference/test-metadata.html#scm-information-git">SCM information</a>). Supported hosts are <code>github.com</code>, <code>gitlab.com</code>, <code>bitbucket.org</code> and self-hosted GitLab. List each self-hosted GitLab host in <a href="/reference/configuration.html#integrations"><code>PIWI_SCM_GITLAB_HOSTS</code></a>: the remote URL comes from the reporter, so Piwi sends the token only to a host you named. A run without a remote URL has nothing to diff.</p><h3 id="scopes" tabindex="-1">Scopes <a class="header-anchor" href="#scopes" aria-label="Permalink to &quot;Scopes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Host</th><th>Read features</th><th>Write features</th></tr></thead><tbody><tr><td>GitHub</td><td>read access to repository contents</td><td><code>repo</code> (classic), or fine-grained <code>contents: write</code> and <code>pull_requests: write</code>; <code>actions: write</code> (classic <code>workflow</code>) for re-runs</td></tr><tr><td>GitLab</td><td><code>read_api</code></td><td><code>api</code></td></tr><tr><td>Bitbucket</td><td>repository read</td><td>repository write; <code>pipeline:write</code> for re-runs</td></tr></tbody></table><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Open a failure cluster from a run that has a commit. The <strong>What changed</strong> panel lists the commits since the last green run. The diagnosis context preview (<strong>Context sent to AI</strong>) shows the same thing in its data coverage: when the SCM section is absent, it says why.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>No commits or diff.</strong> The cluster&#39;s <strong>What changed</strong> line and the coverage name the cause: no commit or repository URL on the run (the reporter reads both from the Git checkout the tests run in, the URL from its <code>origin</code> remote), a host Piwi does not read, no SCM token, or the host&#39;s error. A 404 from GitHub on a private repository means the token cannot see it. On the desktop app, it says when the linked folder does not have the commits yet. While the diff is missing, the line still links the range on the host&#39;s compare page and copies the <code>git log</code> command for it.</li><li><strong>No baseline.</strong> The diff starts at the last green run before the failure first appeared; a project with no green run falls back to the last run where the test passed, and a manual baseline commit overrides both.</li><li><strong>No pull-request comment.</strong> Pull-request feedback also needs <code>PIWI_SITE_URL</code> and a write-scoped token, and posts on GitHub and GitLab only.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./ai-provider.html">AI provider</a>: the model that reads this context</li><li><a href="/features/pr-feedback.html">Pull-request feedback &amp; re-run</a>: what gets posted on a pull request</li><li><a href="./privacy.html">Privacy &amp; data flow</a>: what Piwi sends to your Git host</li></ul>',21)])])}const p=t(s,[["render",i]]);export{f as __pageData,p as default};
